#include "goal1_reference_connection_ad.hpp"
#include <iostream>
#include <iomanip>
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int index;Real x[3];z4c::hyperboloidal::LayerReference<Real>ref(1.,.5,{true,.05,.95});while(std::cin>>index>>x[0]>>x[1]>>x[2]){auto p=ref.At(x[0],x[1],x[2]);auto result=cubed_sphere::reference_connection_ad::Build(ref,p,x);std::cout<<"{\"case\":"<<index<<",\"x\":["<<x[0]<<","<<x[1]<<","<<x[2]<<"],\"Omega\":"<<p.omega<<",\"valid\":"<<(result.connection.valid?"true":"false")<<",\"connection\":[";for(int k=0;k<4;++k)for(int i=0;i<3;++i)for(int j=0;j<3;++j){if(k||i||j)std::cout<<",";const auto&q=result.connection.scaled[k][i][j];std::cout<<"["<<q.f;for(Real d:q.d)std::cout<<","<<d;std::cout<<"]";}std::cout<<"],\"omega_third\":[";for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int k=0;k<3;++k)std::cout<<(i||j||k?",":"")<<result.omega_third[i][j][k];std::cout<<"]}"<<std::endl;}Kokkos::finalize();return 0;}
